import type { Locale } from "@/i18n/config";
import type { ExplorerComicTopic } from "./explorer-comic-topics";

/**
 * Full narration transcripts for each Explorer comic, transcribed
 * directly from the comic's own visible text (title, dialogue,
 * narration boxes, key idea, vocabulary) in panel reading order — not
 * the separate lesson-content fields (shortIntroduction/explanation/
 * story) those comics replaced, and not OCR.
 *
 * All 9 locales are wired to narration — ExplorerComicLesson picks
 * this file's entry for whichever locale is selected, matching the
 * localized comic image now supplied for every language. Keep every
 * language's wording in sync with its own comic's visible text if
 * that comic's text ever changes, the same way this file was built
 * from the English one.
 */
export const explorerComicTranscripts: Record<ExplorerComicTopic, Record<Locale, string>> = {
  needs_wants: {
    en: "Need It or Want It? Some things you must have. Some things you just really, really like. Let's tell them apart! Key idea: a need is something you must have to be okay. A want is something nice to have, even if you really like it. Needs are things you must have. You can't skip them, like food, a warm coat, and a safe place to sleep. Wants are things that are nice to have, but you can still be okay without them, like a new toy, a chocolate bar, or extra stickers. So, is food a need or a want? It's a need! We must have food to be healthy and strong. And a new toy is a want, because it's nice to have, but we can be okay without it. New words: a need is something you must have. A want is something nice to have, but not essential.",
    ro: "Ai nevoie sau îți dorești? Unele lucruri trebuie să le ai. Altele doar îți plac foarte, foarte mult. Hai să le deosebim! Idee cheie: o nevoie este ceva ce trebuie să ai ca să fii bine. O dorință este ceva plăcut de avut, chiar dacă îți place foarte mult. Nevoile sunt lucruri pe care trebuie să le ai. Nu le poți sări peste, cum ar fi mâncarea, o haină călduroasă și un loc sigur unde să dormi. Dorințele sunt lucruri plăcute de avut, dar poți fi bine și fără ele, cum ar fi o jucărie nouă, o ciocolată sau abțibilduri în plus. Deci, mâncarea e o nevoie sau o dorință? E o nevoie! Trebuie să mâncăm ca să fim sănătoși și puternici. Iar o jucărie nouă e o dorință, pentru că e plăcută de avut, dar putem fi bine și fără ea. Cuvinte noi: o nevoie este ceva ce trebuie să ai. O dorință este ceva plăcut de avut, dar nu esențial.",
    es: "¿Lo necesitas o lo quieres? Hay cosas que debes tener. Hay cosas que simplemente te gustan muchísimo. ¡Vamos a diferenciarlas! Idea clave: una necesidad es algo que debes tener para estar bien. Un deseo es algo agradable de tener, aunque te guste mucho. Las necesidades son cosas que debes tener. No puedes saltártelas, como la comida, un abrigo de invierno y un lugar seguro donde dormir. Los deseos son cosas agradables de tener, pero puedes estar bien sin ellas, como un juguete nuevo, una chocolatina o pegatinas extra. Entonces, ¿la comida es una necesidad o un deseo? ¡Es una necesidad! Debemos comer para estar sanos y fuertes. Y un juguete nuevo es un deseo, porque es agradable tenerlo, pero podemos estar bien sin él. Palabras nuevas: una necesidad es algo que debes tener. Un deseo es algo agradable de tener, pero no esencial.",
    fr: "Besoin ou envie ? Il y a des choses que tu dois avoir. Il y a des choses que tu aimes juste énormément. Apprenons à les différencier ! Idée clé : un besoin est quelque chose que tu dois avoir pour aller bien. Une envie est quelque chose d'agréable à avoir, même si tu l'aimes beaucoup. Les besoins sont des choses que tu dois avoir. Tu ne peux pas t'en passer, comme la nourriture, un manteau chaud et un endroit sûr pour dormir. Les envies sont des choses agréables à avoir, mais tu peux très bien t'en passer, comme un nouveau jouet, une tablette de chocolat ou des autocollants en plus. Alors, la nourriture, c'est un besoin ou une envie ? C'est un besoin ! Nous devons manger pour être en bonne santé et forts. Et un nouveau jouet, c'est une envie, parce que c'est agréable à avoir, mais on peut très bien s'en passer. Nouveaux mots : un besoin est quelque chose que tu dois avoir. Une envie est quelque chose d'agréable à avoir, mais pas indispensable.",
    de: "Brauchst du es oder willst du es? Manche Dinge musst du haben. Manche Dinge magst du einfach wirklich sehr. Lass uns den Unterschied herausfinden! Kernidee: Ein Bedürfnis ist etwas, das du haben musst, um in Ordnung zu sein. Ein Wunsch ist etwas Schönes, das man haben kann, auch wenn man es wirklich mag. Bedürfnisse sind Dinge, die du haben musst. Du kannst nicht darauf verzichten, wie Essen, eine warme Jacke und ein sicherer Ort zum Schlafen. Wünsche sind Dinge, die schön zu haben sind, aber du kommst auch ohne sie klar, wie ein neues Spielzeug, eine Tafel Schokolade oder zusätzliche Aufkleber. Ist Essen also ein Bedürfnis oder ein Wunsch? Es ist ein Bedürfnis! Wir müssen essen, um gesund und stark zu sein. Und ein neues Spielzeug ist ein Wunsch, weil es schön ist, es zu haben, aber wir kommen auch ohne es klar. Neue Wörter: Ein Bedürfnis ist etwas, das du haben musst. Ein Wunsch ist etwas Schönes, das man haben kann, aber nicht notwendig ist.",
    it: "Ne hai bisogno o lo desideri? Ci sono cose che devi avere per forza. Ci sono cose che semplicemente ti piacciono moltissimo. Impariamo a distinguerle! Idea chiave: un bisogno è qualcosa che devi avere per stare bene. Un desiderio è qualcosa di piacevole da avere, anche se ti piace molto. I bisogni sono cose che devi avere. Non puoi farne a meno, come il cibo, un cappotto caldo e un posto sicuro dove dormire. I desideri sono cose piacevoli da avere, ma puoi stare bene anche senza, come un gioco nuovo, una tavoletta di cioccolato o adesivi extra. Allora, il cibo è un bisogno o un desiderio? È un bisogno! Dobbiamo mangiare per essere sani e forti. E un gioco nuovo è un desiderio, perché è piacevole averlo, ma possiamo stare bene anche senza. Parole nuove: un bisogno è qualcosa che devi avere. Un desiderio è qualcosa di piacevole da avere, ma non essenziale.",
    pt: "Precisas ou desejas? Há coisas que tens mesmo de ter. Há coisas de que só gostas muito, muito. Vamos aprender a distingui-las! Ideia-chave: uma necessidade é algo que tens de ter para estares bem. Um desejo é algo agradável de ter, mesmo que gostes muito dele. As necessidades são coisas que tens de ter. Não podes passar sem elas, como comida, um casaco quente e um lugar seguro para dormir. Os desejos são coisas agradáveis de ter, mas podes ficar bem sem elas, como um brinquedo novo, uma barra de chocolate ou autocolantes extra. Então, a comida é uma necessidade ou um desejo? É uma necessidade! Temos de comer para sermos saudáveis e fortes. E um brinquedo novo é um desejo, porque é agradável tê-lo, mas podemos ficar bem sem ele. Palavras novas: uma necessidade é algo que tens de ter. Um desejo é algo agradável de ter, mas não essencial.",
    nl: "Nodig of leuk om te hebben? Sommige dingen moet je hebben. Sommige dingen vind je gewoon heel, heel leuk. Laten we het verschil ontdekken! Kernidee: een behoefte is iets wat je moet hebben om in orde te zijn. Een wens is iets fijns om te hebben, zelfs als je het heel leuk vindt. Behoeften zijn dingen die je moet hebben. Je kunt er niet zonder, zoals eten, een warme jas en een veilige plek om te slapen. Wensen zijn dingen die fijn zijn om te hebben, maar je kunt er ook prima zonder, zoals een nieuw speeltje, een chocoladereep of extra stickers. Is eten dan een behoefte of een wens? Het is een behoefte! We moeten eten om gezond en sterk te zijn. En een nieuw speeltje is een wens, want het is fijn om te hebben, maar we kunnen er ook zonder. Nieuwe woorden: een behoefte is iets wat je moet hebben. Een wens is iets fijns om te hebben, maar niet noodzakelijk.",
    pl: "Potrzebujesz tego czy tego chcesz? Są rzeczy, które musisz mieć. Są rzeczy, które po prostu bardzo, bardzo lubisz. Nauczmy się je rozróżniać! Najważniejsza myśl: potrzeba to coś, co musisz mieć, żeby było ci dobrze. Zachcianka to coś przyjemnego, co miło jest mieć, nawet jeśli bardzo to lubisz. Potrzeby to rzeczy, które musisz mieć. Nie możesz się bez nich obejść, jak jedzenie, ciepła kurtka i bezpieczne miejsce do spania. Zachcianki to rzeczy przyjemne, ale możesz się bez nich obejść, jak nowa zabawka, tabliczka czekolady czy dodatkowe naklejki. Czy więc jedzenie to potrzeba czy zachcianka? To potrzeba! Musimy jeść, żeby być zdrowi i silni. A nowa zabawka to zachcianka, bo miło ją mieć, ale możemy się bez niej obejść. Nowe słowa: potrzeba to coś, co musisz mieć. Zachcianka to coś przyjemnego, ale niekonieczne.",
  },
  money_basics: {
    en: "What Is Money? Coins jingle. Notes rustle. But what is money, really? Let's find out together! Key idea: money is something we trade for the things we want or need, instead of swapping items directly. A long, long time ago, people used to swap things directly. A chicken for some bread, maybe? That got tricky fast! Money made it much simpler! Everyone agrees that coins and notes are worth something, so you can use them to get almost anything. New word: money means coins and notes we use to buy things.",
    ro: "Ce este banul? Monedele zornăie. Bancnotele foșnesc. Dar ce sunt banii, de fapt? Hai să aflăm împreună! Idee cheie: banii sunt ceva ce schimbăm pentru lucrurile pe care ni le dorim sau de care avem nevoie, în loc să facem schimb de obiecte direct. Cu mult, mult timp în urmă, oamenii făceau schimb de lucruri direct. O găină pentru niște pâine, poate? S-a complicat repede! Banii au simplificat totul! Toată lumea e de acord că monedele și bancnotele au valoare, așa că le poți folosi ca să obții aproape orice. Cuvânt nou: banii sunt monedele și bancnotele pe care le folosim ca să cumpărăm lucruri.",
    es: "¿Qué es el dinero? Las monedas tintinean. Los billetes crujen. Pero, ¿qué es el dinero en realidad? ¡Vamos a descubrirlo juntos! Idea clave: el dinero es algo que intercambiamos por las cosas que queremos o necesitamos, en lugar de intercambiar objetos directamente. Hace mucho, mucho tiempo, la gente intercambiaba cosas directamente. ¿Una gallina por un poco de pan, tal vez? ¡Eso se complicó rápido! ¡El dinero lo hizo todo mucho más sencillo! Todos están de acuerdo en que las monedas y los billetes tienen valor, así que puedes usarlos para conseguir casi cualquier cosa. Palabra nueva: el dinero son las monedas y los billetes que usamos para comprar cosas.",
    fr: "Qu'est-ce que l'argent ? Les pièces tintent. Les billets froissent. Mais qu'est-ce que l'argent, vraiment ? Découvrons-le ensemble ! Idée clé : l'argent est quelque chose que l'on échange contre les choses que l'on veut ou dont on a besoin, au lieu d'échanger des objets directement. Il y a très, très longtemps, les gens échangeaient des objets directement. Une poule contre un peu de pain, peut-être ? Ça s'est vite compliqué ! L'argent a tout simplifié ! Tout le monde est d'accord que les pièces et les billets ont de la valeur, donc tu peux les utiliser pour obtenir presque n'importe quoi. Nouveau mot : l'argent, ce sont les pièces et les billets qu'on utilise pour acheter des choses.",
    de: "Was ist Geld? Münzen klimpern. Scheine rascheln. Aber was ist Geld eigentlich? Lass es uns gemeinsam herausfinden! Kernidee: Geld ist etwas, das wir gegen die Dinge eintauschen, die wir wollen oder brauchen, statt Gegenstände direkt zu tauschen. Vor sehr, sehr langer Zeit haben die Menschen Dinge direkt getauscht. Ein Huhn für etwas Brot, vielleicht? Das wurde schnell kompliziert! Geld hat alles viel einfacher gemacht! Alle sind sich einig, dass Münzen und Scheine einen Wert haben, also kannst du damit fast alles bekommen. Neues Wort: Geld sind die Münzen und Scheine, mit denen wir Dinge kaufen.",
    it: "Cos'è il denaro? Le monete tintinnano. Le banconote frusciano. Ma cos'è davvero il denaro? Scopriamolo insieme! Idea chiave: il denaro è qualcosa che scambiamo per le cose che vogliamo o di cui abbiamo bisogno, invece di scambiare direttamente gli oggetti. Tanto, tanto tempo fa, le persone scambiavano le cose direttamente. Una gallina per un po' di pane, forse? La cosa si è complicata in fretta! Il denaro ha reso tutto molto più semplice! Tutti sono d'accordo che monete e banconote hanno un valore, quindi puoi usarle per ottenere quasi tutto. Parola nuova: il denaro sono le monete e le banconote che usiamo per comprare le cose.",
    pt: "O que é o dinheiro? As moedas tilintam. As notas fazem barulho. Mas o que é o dinheiro, na verdade? Vamos descobrir juntos! Ideia-chave: o dinheiro é algo que trocamos pelas coisas que queremos ou de que precisamos, em vez de trocar objetos diretamente. Há muito, muito tempo, as pessoas trocavam coisas diretamente. Uma galinha por um pouco de pão, talvez? Isso complicou-se depressa! O dinheiro tornou tudo muito mais simples! Toda a gente concorda que as moedas e as notas têm valor, por isso podes usá-las para obter quase tudo. Palavra nova: dinheiro são as moedas e as notas que usamos para comprar coisas.",
    nl: "Wat is geld? Munten rinkelen. Briefjes ritselen. Maar wat is geld nou eigenlijk? Laten we het samen ontdekken! Kernidee: geld is iets dat we ruilen voor de dingen die we willen of nodig hebben, in plaats van spullen rechtstreeks te ruilen. Heel, heel lang geleden ruilden mensen spullen rechtstreeks. Een kip voor wat brood, misschien? Dat werd al snel ingewikkeld! Geld maakte alles veel eenvoudiger! Iedereen is het erover eens dat munten en briefjes waarde hebben, dus je kunt er bijna alles mee krijgen. Nieuw woord: geld zijn de munten en briefjes die we gebruiken om dingen te kopen.",
    pl: "Czym są pieniądze? Monety brzęczą. Banknoty szeleszczą. Ale czym naprawdę są pieniądze? Odkryjmy to razem! Najważniejsza myśl: pieniądze to coś, co wymieniamy na rzeczy, których chcemy lub potrzebujemy, zamiast wymieniać się przedmiotami bezpośrednio. Bardzo, bardzo dawno temu ludzie wymieniali się rzeczami bezpośrednio. Kura za trochę chleba, może? To szybko się skomplikowało! Pieniądze znacznie to uprościły! Wszyscy zgadzają się, że monety i banknoty mają wartość, więc można ich używać, by zdobyć prawie wszystko. Nowe słowo: pieniądze to monety i banknoty, których używamy, żeby coś kupić.",
  },
  saving: {
    en: "What Does Saving Mean? What if, instead of spending your coins today, you kept them, and watched the pile grow? Key idea: saving is putting money aside now so you can use it later, often for something bigger. I can save my coins instead of spending them all straight away. I'll have more later because my savings can grow! Then I might have enough for something bigger, like a bike! Saving helps me plan ahead and reach bigger goals. New word: save means to keep money instead of spending it.",
    ro: "Ce înseamnă să economisești? Dacă, în loc să cheltuiești monedele azi, le-ai păstra și ai privi cum crește grămada? Idee cheie: a economisi înseamnă să pui bani deoparte acum ca să îi folosești mai târziu, adesea pentru ceva mai mare. Pot să îmi economisesc monedele în loc să le cheltuiesc pe toate imediat. O să am mai mult mai târziu, pentru că economiile mele pot crește! Apoi aș putea avea destul pentru ceva mai mare, cum ar fi o bicicletă! Economisirea mă ajută să plănuiesc din timp și să ajung la obiective mai mari. Cuvânt nou: a economisi înseamnă să păstrezi banii în loc să îi cheltuiești.",
    es: "¿Qué significa ahorrar? ¿Y si, en lugar de gastar tus monedas hoy, las guardaras y vieras crecer el montón? Idea clave: ahorrar es apartar dinero ahora para poder usarlo más tarde, a menudo para algo más grande. Puedo ahorrar mis monedas en lugar de gastarlas todas de una vez. ¡Tendré más adelante porque mis ahorros pueden crecer! Entonces podría tener suficiente para algo más grande, ¡como una bicicleta! Ahorrar me ayuda a planificar con antelación y alcanzar metas más grandes. Palabra nueva: ahorrar significa guardar el dinero en lugar de gastarlo.",
    fr: "Que veut dire épargner ? Et si, au lieu de dépenser tes pièces aujourd'hui, tu les gardais et regardais le tas grandir ? Idée clé : épargner, c'est mettre de l'argent de côté maintenant pour pouvoir l'utiliser plus tard, souvent pour quelque chose de plus grand. Je peux épargner mes pièces au lieu de toutes les dépenser tout de suite. J'en aurai plus plus tard, car mes économies peuvent grandir ! Ensuite, je pourrais avoir assez pour quelque chose de plus grand, comme un vélo ! Épargner m'aide à planifier à l'avance et à atteindre des objectifs plus grands. Nouveau mot : épargner veut dire garder l'argent au lieu de le dépenser.",
    de: "Was bedeutet Sparen? Was, wenn du deine Münzen heute nicht ausgibst, sondern behältst und zusiehst, wie der Stapel wächst? Kernidee: Sparen heißt, jetzt Geld beiseitezulegen, damit du es später benutzen kannst, oft für etwas Größeres. Ich kann meine Münzen sparen, statt sie alle sofort auszugeben. Später habe ich mehr, weil meine Ersparnisse wachsen können! Dann könnte ich genug für etwas Größeres haben, wie ein Fahrrad! Sparen hilft mir, vorauszuplanen und größere Ziele zu erreichen. Neues Wort: Sparen bedeutet, Geld zu behalten, statt es auszugeben.",
    it: "Cosa vuol dire risparmiare? E se, invece di spendere le tue monete oggi, le tenessi e guardassi il mucchietto crescere? Idea chiave: risparmiare significa mettere da parte denaro adesso per poterlo usare più avanti, spesso per qualcosa di più grande. Posso risparmiare le mie monete invece di spenderle tutte subito. Più avanti ne avrò di più perché i miei risparmi possono crescere! Allora potrei avere abbastanza per qualcosa di più grande, come una bicicletta! Risparmiare mi aiuta a pianificare in anticipo e a raggiungere obiettivi più grandi. Parola nuova: risparmiare significa tenere il denaro invece di spenderlo.",
    pt: "O que significa poupar? E se, em vez de gastares as tuas moedas hoje, as guardasses e visses o monte crescer? Ideia-chave: poupar é pôr dinheiro de parte agora para poderes usá-lo mais tarde, muitas vezes para algo maior. Posso poupar as minhas moedas em vez de as gastar todas logo. Vou ter mais mais tarde, porque as minhas poupanças podem crescer! Depois posso ter o suficiente para algo maior, como uma bicicleta! Poupar ajuda-me a planear com antecedência e a alcançar objetivos maiores. Palavra nova: poupar significa guardar o dinheiro em vez de o gastar.",
    nl: "Wat betekent sparen? Wat als je je munten vandaag niet uitgeeft, maar bewaart en de stapel ziet groeien? Kernidee: sparen is nu geld opzijzetten zodat je het later kunt gebruiken, vaak voor iets groters. Ik kan mijn munten sparen in plaats van ze meteen allemaal uit te geven. Later heb ik meer, omdat mijn spaargeld kan groeien! Dan heb ik misschien genoeg voor iets groters, zoals een fiets! Sparen helpt me vooruit te plannen en grotere doelen te bereiken. Nieuw woord: sparen betekent geld bewaren in plaats van het uit te geven.",
    pl: "Co to znaczy oszczędzać? A gdyby, zamiast wydawać swoje monety dziś, zatrzymać je i patrzeć, jak stosik rośnie? Najważniejsza myśl: oszczędzanie to odkładanie pieniędzy teraz, żeby móc je wykorzystać później, często na coś większego. Mogę oszczędzać moje monety, zamiast wydawać je wszystkie od razu. Później będę miał więcej, bo moje oszczędności mogą rosnąć! Wtedy mógłbym mieć dość na coś większego, na przykład rower! Oszczędzanie pomaga mi planować z wyprzedzeniem i osiągać większe cele. Nowe słowo: oszczędzać znaczy zatrzymywać pieniądze zamiast je wydawać.",
  },
  currencies: {
    en: "Money Looks Different Everywhere. Did you know the coins in your pocket wouldn't work in every country? Let's explore why! Key idea: different countries have their own kind of money, and it looks different from place to place. Just like countries can have different flags, languages, and foods, they also have different money! In the United Kingdom, money is called the pound. In Romania, it's called the leu. In the United States, it's called the dollar. The coins and notes you use every day are made especially for where you live. New words: a country is a place with its own government and rules. Different means not the same.",
    ro: "Banii arată diferit peste tot. Știai că monedele din buzunarul tău n-ar funcționa în orice țară? Hai să descoperim de ce! Idee cheie: fiecare țară are propriul tip de bani, iar aceștia arată diferit de la un loc la altul. Așa cum țările pot avea steaguri, limbi și mâncăruri diferite, tot așa au și bani diferiți! În Regatul Unit, banii se numesc lire sterline. În România, se numesc lei. În Statele Unite, se numesc dolari. Monedele și bancnotele pe care le folosești în fiecare zi sunt făcute special pentru locul unde trăiești. Cuvinte noi: o țară este un loc cu propriul guvern și propriile reguli. Diferit înseamnă nu la fel.",
    es: "El dinero se ve diferente en todas partes. ¿Sabías que las monedas de tu bolsillo no servirían en todos los países? ¡Vamos a descubrir por qué! Idea clave: cada país tiene su propio tipo de dinero, y se ve diferente de un lugar a otro. Igual que los países pueden tener banderas, idiomas y comidas diferentes, ¡también tienen dinero diferente! En el Reino Unido, el dinero se llama libra. En Rumanía, se llama leu. En Estados Unidos, se llama dólar. Las monedas y los billetes que usas cada día se hacen especialmente para el lugar donde vives. Palabras nuevas: un país es un lugar con su propio gobierno y sus propias reglas. Diferente significa que no es igual.",
    fr: "L'argent a un aspect différent partout. Savais-tu que les pièces dans ta poche ne fonctionneraient pas dans tous les pays ? Découvrons pourquoi ! Idée clé : chaque pays a sa propre monnaie, qui a un aspect différent d'un endroit à l'autre. Tout comme les pays peuvent avoir des drapeaux, des langues et des cuisines différents, ils ont aussi une monnaie différente ! Au Royaume-Uni, l'argent s'appelle la livre. En Roumanie, on l'appelle le leu. Aux États-Unis, on l'appelle le dollar. Les pièces et les billets que tu utilises chaque jour sont fabriqués spécialement pour l'endroit où tu vis. Nouveaux mots : un pays est un endroit avec son propre gouvernement et ses propres règles. Différent veut dire pas pareil.",
    de: "Geld sieht überall anders aus. Wusstest du, dass die Münzen in deiner Tasche nicht in jedem Land funktionieren würden? Lass uns herausfinden, warum! Kernidee: Jedes Land hat seine eigene Art von Geld, und es sieht von Ort zu Ort unterschiedlich aus. So wie Länder unterschiedliche Flaggen, Sprachen und Speisen haben können, haben sie auch unterschiedliches Geld! Im Vereinigten Königreich heißt das Geld Pfund. In Rumänien heißt es Leu. In den Vereinigten Staaten heißt es Dollar. Die Münzen und Scheine, die du jeden Tag benutzt, werden extra für den Ort gemacht, an dem du lebst. Neue Wörter: Ein Land ist ein Ort mit seiner eigenen Regierung und eigenen Regeln. Unterschiedlich bedeutet nicht gleich.",
    it: "Il denaro ha un aspetto diverso ovunque. Lo sapevi che le monete nella tua tasca non funzionerebbero in tutti i paesi? Scopriamo perché! Idea chiave: ogni paese ha il proprio tipo di denaro, che ha un aspetto diverso da luogo a luogo. Proprio come i paesi possono avere bandiere, lingue e cibi diversi, hanno anche denaro diverso! Nel Regno Unito, il denaro si chiama sterlina. In Romania si chiama leu. Negli Stati Uniti si chiama dollaro. Le monete e le banconote che usi ogni giorno sono fatte apposta per il posto in cui vivi. Parole nuove: un paese è un luogo con il proprio governo e le proprie regole. Diverso significa non uguale.",
    pt: "O dinheiro tem um aspeto diferente em todo o lado. Sabias que as moedas no teu bolso não funcionariam em todos os países? Vamos descobrir porquê! Ideia-chave: cada país tem o seu próprio tipo de dinheiro, que tem um aspeto diferente de lugar para lugar. Tal como os países podem ter bandeiras, línguas e comidas diferentes, também têm dinheiro diferente! No Reino Unido, o dinheiro chama-se libra. Na Roménia, chama-se leu. Nos Estados Unidos, chama-se dólar. As moedas e as notas que usas todos os dias são feitas especialmente para o lugar onde vives. Palavras novas: um país é um lugar com o seu próprio governo e as suas próprias regras. Diferente significa não ser igual.",
    nl: "Geld ziet er overal anders uit. Wist je dat de munten in je zak niet in elk land zouden werken? Laten we ontdekken waarom! Kernidee: elk land heeft zijn eigen soort geld, dat er van plek tot plek anders uitziet. Net zoals landen verschillende vlaggen, talen en gerechten kunnen hebben, hebben ze ook verschillend geld! In het Verenigd Koninkrijk heet het geld het pond. In Roemenië heet het de leu. In de Verenigde Staten heet het de dollar. De munten en briefjes die je elke dag gebruikt, zijn speciaal gemaakt voor de plek waar je woont. Nieuwe woorden: een land is een plek met zijn eigen regering en regels. Anders betekent niet hetzelfde.",
    pl: "Pieniądze wyglądają inaczej wszędzie. Czy wiesz, że monety z twojej kieszeni nie działałyby w każdym kraju? Odkryjmy dlaczego! Najważniejsza myśl: każdy kraj ma swój własny rodzaj pieniędzy, który wygląda inaczej w różnych miejscach. Tak jak kraje mogą mieć różne flagi, języki i potrawy, tak samo mają różne pieniądze! W Wielkiej Brytanii pieniądze nazywają się funt. W Rumunii nazywają się lej. W Stanach Zjednoczonych nazywają się dolar. Monety i banknoty, których używasz na co dzień, są robione specjalnie dla miejsca, w którym mieszkasz. Nowe słowa: kraj to miejsce z własnym rządem i własnymi zasadami. Inny znaczy nie taki sam.",
  },
  scams: {
    en: "Some Promises Are Too Good. If a message says you've won something you never entered for, that's a big clue something is wrong. It might sound exciting, but it could be a trick! Key idea: a message promising free money or prizes out of nowhere is usually a trick, not a real gift. Wait, I never entered any competition! Real prizes almost never show up out of nowhere from someone you don't know. If something online promises free money or a prize you never asked for, the safest thing to do is tell a grown-up, and not click anything! Stay safe online: be careful with surprise messages, tell a grown-up, and don't click on unknown links. New word: a trick is something that seems true but isn't, meant to fool you.",
    ro: "Unele promisiuni sunt prea bune ca să fie adevărate. Dacă un mesaj spune că ai câștigat ceva la care nu te-ai înscris niciodată, e un semn clar că ceva nu e în regulă. Poate suna interesant, dar ar putea fi o înșelătorie! Idee cheie: un mesaj care promite bani sau premii gratuite din senin este de obicei o înșelătorie, nu un cadou adevărat. Stai puțin... nu m-am înscris la niciun concurs! Premiile adevărate aproape niciodată nu apar din senin de la cineva pe care nu-l cunoști. Dacă ceva online îți promite bani sau un premiu gratuit pe care nu l-ai cerut, cel mai sigur lucru este să spui unui adult și să nu dai click pe nimic! Stai în siguranță online: fii atent la mesajele surprinzătoare, spune unui adult și nu da click pe linkuri necunoscute. Cuvânt nou: o înșelătorie este ceva care pare adevărat, dar nu este, menit să te păcălească.",
    es: "Algunas promesas son demasiado buenas. Si un mensaje dice que has ganado algo a lo que nunca te apuntaste, esa es una señal clara de que algo va mal. Puede sonar emocionante, ¡pero podría ser un engaño! Idea clave: un mensaje que promete dinero o premios gratis de la nada suele ser un engaño, no un regalo de verdad. Espera… ¡nunca me apunté a ningún concurso! Los premios de verdad casi nunca aparecen de la nada de parte de alguien que no conoces. Si algo en internet promete dinero gratis o un premio que no pediste, lo más seguro es decírselo a una persona adulta y no hacer clic en nada. Mantente seguro en internet: ten cuidado con los mensajes sorpresa, díselo a una persona adulta y no hagas clic en enlaces desconocidos. Palabra nueva: un engaño es algo que parece verdad pero no lo es, pensado para engañarte.",
    fr: "Certaines promesses sont trop belles. Si un message dit que tu as gagné quelque chose auquel tu ne t'es jamais inscrit, c'est un gros indice que quelque chose ne va pas. Ça peut sembler excitant, mais ça pourrait être une arnaque ! Idée clé : un message qui promet de l'argent ou des prix gratuits, sortis de nulle part, est généralement une arnaque, pas un vrai cadeau. Attends… je ne me suis inscrit à aucun concours ! Les vrais prix n'apparaissent presque jamais comme ça, venant de quelqu'un que tu ne connais pas. Si quelque chose en ligne promet de l'argent gratuit ou un prix que tu n'as jamais demandé, le plus sûr est d'en parler à un adulte et de ne cliquer sur rien ! Reste en sécurité en ligne : méfie-toi des messages surprenants, parle-s-en à un adulte, et ne clique pas sur des liens inconnus. Nouveau mot : une arnaque est quelque chose qui semble vrai mais ne l'est pas, fait pour te tromper.",
    de: "Manche Versprechen sind zu schön. Wenn eine Nachricht sagt, du hättest etwas gewonnen, wofür du dich nie angemeldet hast, ist das ein großer Hinweis, dass etwas nicht stimmt. Es mag aufregend klingen, aber es könnte ein Trick sein! Kernidee: Eine Nachricht, die aus heiterem Himmel kostenloses Geld oder Preise verspricht, ist meist ein Trick, kein echtes Geschenk. Moment mal, ich habe an keinem Wettbewerb teilgenommen! Echte Preise tauchen fast nie einfach so von jemandem auf, den du nicht kennst. Wenn etwas im Internet kostenloses Geld oder einen Preis verspricht, um den du nie gebeten hast, ist es am sichersten, es einem Erwachsenen zu sagen und nirgendwo draufzuklicken! Sicher im Internet bleiben: Sei vorsichtig bei überraschenden Nachrichten, sag es einem Erwachsenen, und klicke nicht auf unbekannte Links. Neues Wort: Ein Trick ist etwas, das wahr erscheint, es aber nicht ist, um dich zu täuschen.",
    it: "Alcune promesse sono troppo belle. Se un messaggio dice che hai vinto qualcosa a cui non ti sei mai iscritto, è un grande indizio che qualcosa non va. Può sembrare emozionante, ma potrebbe essere un trucco! Idea chiave: un messaggio che promette soldi o premi gratis dal nulla è di solito un trucco, non un vero regalo. Aspetta… non mi sono iscritto a nessun concorso! I premi veri quasi mai arrivano dal nulla da qualcuno che non conosci. Se qualcosa online promette soldi gratis o un premio che non hai mai chiesto, la cosa più sicura è dirlo a un adulto e non cliccare su niente! Resta al sicuro online: fai attenzione ai messaggi a sorpresa, dillo a un adulto e non cliccare su link sconosciuti. Parola nuova: un trucco è qualcosa che sembra vero ma non lo è, fatto apposta per ingannarti.",
    pt: "Algumas promessas são boas demais. Se uma mensagem diz que ganhaste algo a que nunca te inscreveste, essa é uma grande pista de que algo está errado. Pode parecer excitante, mas pode ser uma armadilha! Ideia-chave: uma mensagem que promete dinheiro ou prémios grátis, vindos do nada, costuma ser uma armadilha, não um presente verdadeiro. Espera… nunca me inscrevi em nenhum concurso! Os prémios verdadeiros quase nunca aparecem do nada, de alguém que não conheces. Se algo online promete dinheiro grátis ou um prémio que nunca pediste, o mais seguro é contar a um adulto e não clicar em nada! Mantém-te seguro online: tem cuidado com mensagens surpresa, conta a um adulto e não cliques em links desconhecidos. Palavra nova: uma armadilha é algo que parece verdade mas não é, feito para te enganar.",
    nl: "Sommige beloftes zijn te mooi om waar te zijn. Als een bericht zegt dat je iets hebt gewonnen waarvoor je je nooit hebt aangemeld, is dat een groot teken dat er iets mis is. Het klinkt misschien spannend, maar het kan een truc zijn! Kernidee: een bericht dat uit het niets gratis geld of prijzen belooft, is meestal een truc, geen echt cadeau. Wacht even… ik heb me nooit aangemeld voor een wedstrijd! Echte prijzen komen bijna nooit zomaar uit het niets van iemand die je niet kent. Als iets online gratis geld of een prijs belooft die je nooit hebt gevraagd, is het veiligst om het aan een volwassene te vertellen en nergens op te klikken! Veilig online blijven: wees voorzichtig met verrassende berichten, vertel het een volwassene, en klik niet op onbekende links. Nieuw woord: een truc is iets dat echt lijkt, maar het niet is, bedoeld om je voor de gek te houden.",
    pl: "Niektóre obietnice są zbyt piękne. Jeśli wiadomość mówi, że wygrałeś coś, do czego nigdy się nie zgłosiłeś, to duży sygnał, że coś jest nie tak. Może brzmieć ekscytująco, ale to może być oszustwo! Najważniejsza myśl: wiadomość obiecująca darmowe pieniądze lub nagrody znikąd to zwykle oszustwo, a nie prawdziwy prezent. Czekaj… nigdy nie zgłosiłem się do żadnego konkursu! Prawdziwe nagrody prawie nigdy nie pojawiają się znikąd od kogoś, kogo nie znasz. Jeśli coś w internecie obiecuje darmowe pieniądze lub nagrodę, o którą nigdy nie prosiłeś, najbezpieczniej jest powiedzieć o tym dorosłemu i nigdzie nie klikać! Zachowaj bezpieczeństwo w internecie: uważaj na niespodziewane wiadomości, powiedz dorosłemu i nie klikaj w nieznane linki. Nowe słowo: oszustwo to coś, co wydaje się prawdziwe, ale nie jest, i ma na celu cię oszukać.",
  },
  long_term_thinking: {
    en: "Waiting Can Pay Off. Sometimes the best things come to the people who can wait just a little bit. Let's see why waiting can be a good idea! Key idea: waiting a little bit can sometimes get you more than rushing to have something right away. I really want this toy car now! I could save my pocket money for a few weeks. I did it! I waited, saved, and now I can afford it! Rushing: you might get something quickly, but it may not be the best choice. Waiting: you can save, choose carefully, and often get something better! New words: to wait means to not do something right away. Patient means being able to wait calmly without rushing.",
    ro: "Așteptarea poate avea rost. Uneori, cele mai bune lucruri vin către cei care pot aștepta puțin. Hai să vedem de ce așteptarea poate fi o idee bună! Idee cheie: dacă aștepți puțin, câteodată poți obține mai mult decât dacă te grăbești să ai ceva imediat. Vreau foarte mult această mașinuță acum! Aș putea să-mi economisesc banii de buzunar câteva săptămâni. Am reușit! Am așteptat, am economisit și acum mi-o pot permite! Grabă: poți obține ceva repede, dar s-ar putea să nu fie cea mai bună alegere. Așteptare: poți economisi, alege cu grijă și, de multe ori, obții ceva mai bun! Cuvinte noi: a aștepta înseamnă a nu face ceva imediat. Răbdător înseamnă să poți aștepta calm, fără să te grăbești.",
    es: "Esperar puede valer la pena. A veces, las mejores cosas llegan a quienes pueden esperar un poco. ¡Vamos a ver por qué esperar puede ser una buena idea! Idea clave: esperar un poco a veces te da más que apresurarte a tener algo de inmediato. ¡Quiero muchísimo este coche de juguete ahora mismo! Podría ahorrar mi paga durante unas semanas. ¡Lo logré! Esperé, ahorré, y ahora puedo comprarlo. Apresurarse: puedes conseguir algo rápido, pero puede que no sea la mejor opción. Esperar: puedes ahorrar, elegir con cuidado y, a menudo, conseguir algo mejor. Palabras nuevas: esperar significa no hacer algo de inmediato. Paciente significa ser capaz de esperar con calma sin apresurarte.",
    fr: "Attendre peut en valoir la peine. Parfois, les meilleures choses arrivent à ceux qui savent attendre un peu. Voyons pourquoi attendre peut être une bonne idée ! Idée clé : attendre un peu peut parfois te donner plus que te précipiter pour avoir quelque chose tout de suite. Je veux vraiment cette petite voiture maintenant ! Je pourrais épargner mon argent de poche pendant quelques semaines. J'ai réussi ! J'ai attendu, j'ai épargné, et maintenant je peux me l'offrir ! Se précipiter : tu peux obtenir quelque chose vite, mais ce n'est peut-être pas le meilleur choix. Attendre : tu peux épargner, choisir avec soin et souvent obtenir quelque chose de mieux ! Nouveaux mots : attendre veut dire ne pas faire quelque chose tout de suite. Patient veut dire être capable d'attendre calmement sans se précipiter.",
    de: "Warten kann sich lohnen. Manchmal kommen die besten Dinge zu denen, die ein wenig warten können. Schauen wir uns an, warum Warten eine gute Idee sein kann! Kernidee: Ein bisschen zu warten kann dir manchmal mehr bringen, als dich zu beeilen, um etwas sofort zu haben. Ich will dieses Spielzeugauto jetzt wirklich! Ich könnte mein Taschengeld ein paar Wochen lang sparen. Ich habe es geschafft! Ich habe gewartet, gespart, und jetzt kann ich es mir leisten! Sich beeilen: Du bekommst vielleicht schnell etwas, aber es ist vielleicht nicht die beste Wahl. Warten: Du kannst sparen, sorgfältig wählen und bekommst oft etwas Besseres! Neue Wörter: Warten bedeutet, etwas nicht sofort zu tun. Geduldig bedeutet, ruhig warten zu können, ohne sich zu beeilen.",
    it: "Aspettare può valerne la pena. A volte le cose migliori arrivano a chi sa aspettare un po'. Vediamo perché aspettare può essere una buona idea! Idea chiave: aspettare un po' a volte ti dà più di quanto ottieni avendo subito fretta di avere qualcosa. Voglio davvero questa macchinina adesso! Potrei risparmiare la mia paghetta per qualche settimana. Ce l'ho fatta! Ho aspettato, ho risparmiato, e ora posso permettermela! Avere fretta: puoi ottenere qualcosa in fretta, ma potrebbe non essere la scelta migliore. Aspettare: puoi risparmiare, scegliere con attenzione e spesso ottenere qualcosa di meglio! Parole nuove: aspettare significa non fare subito qualcosa. Paziente significa essere capace di aspettare con calma senza avere fretta.",
    pt: "Esperar pode valer a pena. Às vezes, as melhores coisas chegam a quem consegue esperar um pouco. Vamos ver porque esperar pode ser uma boa ideia! Ideia-chave: esperar um pouco às vezes dá-te mais do que teres pressa em ter algo de imediato. Quero mesmo muito este carrinho agora! Podia poupar a minha mesada durante algumas semanas. Consegui! Esperei, poupei, e agora posso comprá-lo! Ter pressa: podes conseguir algo depressa, mas pode não ser a melhor escolha. Esperar: podes poupar, escolher com cuidado e muitas vezes conseguir algo melhor! Palavras novas: esperar significa não fazer algo de imediato. Paciente significa ser capaz de esperar com calma, sem pressa.",
    nl: "Wachten kan lonen. Soms komen de beste dingen naar wie een beetje kan wachten. Laten we kijken waarom wachten een goed idee kan zijn! Kernidee: een beetje wachten kan je soms meer opleveren dan je haasten om iets meteen te hebben. Ik wil dit speelgoedautootje nu echt graag! Ik zou mijn zakgeld een paar weken kunnen sparen. Het is me gelukt! Ik heb gewacht, gespaard, en nu kan ik het me veroorloven! Haasten: je krijgt misschien snel iets, maar het is misschien niet de beste keuze. Wachten: je kunt sparen, zorgvuldig kiezen en vaak iets beters krijgen! Nieuwe woorden: wachten betekent iets niet meteen doen. Geduldig betekent kalm kunnen wachten zonder te haasten.",
    pl: "Czekanie może się opłacać. Czasami najlepsze rzeczy trafiają do tych, którzy potrafią trochę poczekać. Zobaczmy, dlaczego czekanie może być dobrym pomysłem! Najważniejsza myśl: trochę czekania może czasem dać ci więcej niż pośpiech, by mieć coś od razu. Bardzo chcę ten samochodzik teraz! Mógłbym oszczędzać kieszonkowe przez kilka tygodni. Udało mi się! Czekałem, oszczędzałem, i teraz mnie na niego stać! Pośpiech: możesz dostać coś szybko, ale może to nie być najlepszy wybór. Czekanie: możesz oszczędzać, wybierać uważnie i często dostać coś lepszego! Nowe słowa: czekać znaczy nie robić czegoś od razu. Cierpliwy znaczy potrafić czekać spokojnie, bez pośpiechu.",
  },
  giving: {
    en: "The Joy of Sharing. Sharing a little of what you have can feel just as good as getting something new. Let's see why sharing is so special! Key idea: giving away some of what you have to help someone else is a kind, valuable choice, not a loss. You don't need a lot of coins to be able to give. Even a small amount can make a real difference to someone else, and it can feel really good to help. The big idea: you can share money, things, or your time. It can help someone who needs a little extra. It feels good to be kind and give. New words: to give means to let someone else have something of yours. To share means to let others use or have part of what you have.",
    ro: "Bucuria de a împărți. Să împarți puțin din ce ai poate să te facă să te simți la fel de bine ca atunci când primești ceva nou. Hai să vedem de ce e atât de special să împarți! Idee cheie: să dai o parte din ce ai ca să ajuți pe altcineva este o alegere bună și valoroasă, nu o pierdere. Nu ai nevoie de multe monede ca să poți dărui. Chiar și o sumă mică poate face o diferență reală pentru altcineva, și te poate face să te simți foarte bine că ai ajutat. Ideea mare: poți împărți bani, lucruri sau timpul tău. Poate ajuta pe cineva care are nevoie de puțin mai mult. Te simți bine când ești bun și dăruiești. Cuvinte noi: a dărui înseamnă a lăsa pe altcineva să aibă ceva ce îți aparține. A împărți înseamnă a-i lăsa pe alții să folosească sau să aibă o parte din ce ai tu.",
    es: "La alegría de compartir. Compartir un poco de lo que tienes puede sentirse tan bien como recibir algo nuevo. ¡Vamos a ver por qué compartir es tan especial! Idea clave: dar parte de lo que tienes para ayudar a otra persona es una elección buena y valiosa, no una pérdida. No necesitas muchas monedas para poder dar. Incluso una pequeña cantidad puede suponer una diferencia real para otra persona, y puede sentirse muy bien ayudar. La gran idea: puedes compartir dinero, cosas o tu tiempo. Puede ayudar a alguien que necesita un poco más. Se siente bien ser amable y dar. Palabras nuevas: dar significa dejar que otra persona tenga algo tuyo. Compartir significa dejar que otros usen o tengan parte de lo que tienes.",
    fr: "La joie de partager. Partager un peu de ce que tu as peut faire du bien, tout autant que de recevoir quelque chose de nouveau. Voyons pourquoi partager est si spécial ! Idée clé : donner une partie de ce que tu as pour aider quelqu'un d'autre est un choix gentil et précieux, pas une perte. Tu n'as pas besoin de beaucoup de pièces pour pouvoir donner. Même une petite somme peut vraiment faire la différence pour quelqu'un d'autre, et ça peut faire vraiment du bien d'aider. La grande idée : tu peux partager de l'argent, des objets ou ton temps. Ça peut aider quelqu'un qui a besoin d'un petit coup de pouce. Ça fait du bien d'être gentil et de donner. Nouveaux mots : donner veut dire laisser quelqu'un d'autre avoir quelque chose qui t'appartient. Partager veut dire laisser les autres utiliser ou avoir une partie de ce que tu as.",
    de: "Die Freude am Teilen. Ein wenig von dem zu teilen, was du hast, kann sich genauso gut anfühlen wie etwas Neues zu bekommen. Schauen wir uns an, warum Teilen so besonders ist! Kernidee: etwas von dem wegzugeben, was du hast, um jemand anderem zu helfen, ist eine gute, wertvolle Entscheidung, kein Verlust. Du brauchst nicht viele Münzen, um geben zu können. Sogar ein kleiner Betrag kann für jemand anderen einen echten Unterschied machen, und es kann sich richtig gut anfühlen zu helfen. Die große Idee: Du kannst Geld, Dinge oder deine Zeit teilen. Es kann jemandem helfen, der ein bisschen mehr braucht. Es fühlt sich gut an, freundlich zu sein und zu geben. Neue Wörter: Geben bedeutet, jemand anderem etwas von dir zu überlassen. Teilen bedeutet, andere etwas benutzen zu lassen oder ihnen einen Teil von dem zu geben, was du hast.",
    it: "La gioia di condividere. Condividere un po' di quello che hai può far sentire bene quanto ricevere qualcosa di nuovo. Vediamo perché condividere è così speciale! Idea chiave: dare parte di ciò che hai per aiutare qualcun altro è una scelta gentile e preziosa, non una perdita. Non ti servono tante monete per poter dare. Anche una piccola somma può fare una vera differenza per qualcun altro, e può far sentire davvero bene aiutare. L'idea grande: puoi condividere denaro, oggetti o il tuo tempo. Può aiutare qualcuno che ha bisogno di un po' di più. Fa bene essere gentili e dare. Parole nuove: dare significa lasciare che qualcun altro abbia qualcosa di tuo. Condividere significa lasciare che altri usino o abbiano parte di ciò che hai.",
    pt: "A alegria de partilhar. Partilhar um pouco do que tens pode fazer-te sentir tão bem como receber algo novo. Vamos ver porque partilhar é tão especial! Ideia-chave: dar parte do que tens para ajudar outra pessoa é uma escolha boa e valiosa, não uma perda. Não precisas de muitas moedas para poderes dar. Mesmo uma pequena quantia pode fazer uma diferença real para outra pessoa, e ajudar pode fazer-te sentir mesmo bem. A grande ideia: podes partilhar dinheiro, coisas ou o teu tempo. Pode ajudar alguém que precisa de um pouco mais. Sabe bem ser gentil e dar. Palavras novas: dar significa deixar outra pessoa ficar com algo teu. Partilhar significa deixar os outros usar ou ter parte do que tens.",
    nl: "De vreugde van delen. Een beetje delen van wat je hebt, kan net zo goed voelen als iets nieuws krijgen. Laten we kijken waarom delen zo bijzonder is! Kernidee: een deel van wat je hebt weggeven om iemand anders te helpen, is een vriendelijke, waardevolle keuze, geen verlies. Je hebt niet veel munten nodig om te kunnen geven. Zelfs een klein bedrag kan een echt verschil maken voor iemand anders, en helpen kan heel goed voelen. Het grote idee: je kunt geld, spullen of je tijd delen. Het kan iemand helpen die een beetje extra nodig heeft. Het voelt goed om aardig te zijn en te geven. Nieuwe woorden: geven betekent iemand anders iets van jou laten hebben. Delen betekent anderen iets laten gebruiken of een deel laten hebben van wat jij hebt.",
    pl: "Radość dzielenia się. Podzielenie się odrobiną tego, co masz, może być tak samo przyjemne, jak otrzymanie czegoś nowego. Zobaczmy, dlaczego dzielenie się jest takie wyjątkowe! Najważniejsza myśl: oddanie części tego, co masz, żeby pomóc komuś innemu, to dobry, wartościowy wybór, a nie strata. Nie potrzebujesz wielu monet, żeby móc dawać. Nawet niewielka kwota może naprawdę coś zmienić dla kogoś innego, a pomaganie może sprawiać naprawdę dobre uczucie. Najważniejsza myśl: możesz dzielić się pieniędzmi, rzeczami lub swoim czasem. Może to pomóc komuś, kto potrzebuje odrobinę więcej. Dobrze jest być miłym i dawać. Nowe słowa: dawać znaczy pozwolić komuś innemu mieć coś twojego. Dzielić się znaczy pozwolić innym korzystać z części tego, co masz, albo mieć jej część.",
  },
  digital_money: {
    en: "Money You Can't Hold. Sometimes money doesn't look like coins at all. Let's see what that means! So money can be digital? Key idea: money can be digital, numbers that move between accounts, not just physical coins and notes you can hold. When Mum tapped her card, no coins or notes changed hands. Instead, a number went down in her account, and a number went up in the shop's account. Payment received! It's still real money, it just moves in a different way. New word: digital money is money that exists as numbers on a computer, not as coins or notes you can hold.",
    ro: "Banii pe care nu îi poți ține în mână. Uneori, banii nu arată deloc ca monedele. Hai să vedem ce înseamnă asta! Deci banii pot fi digitali? Idee cheie: banii pot fi digitali, adică niște numere care se mută între conturi, nu doar monede și bancnote fizice pe care le poți ține în mână. Când mama a atins cardul, nicio monedă sau bancnotă nu a schimbat mâna. În schimb, un număr a scăzut în contul ei, iar un număr a crescut în contul magazinului. Plată primită! Sunt tot bani adevărați, doar că se mută într-un alt fel. Cuvânt nou: banii digitali sunt bani care există ca numere pe un calculator, nu ca monede sau bancnote pe care le poți ține în mână.",
    es: "El dinero que no puedes sostener. A veces, el dinero no se parece nada a las monedas. ¡Vamos a ver qué significa eso! Entonces, ¿el dinero puede ser digital? Idea clave: el dinero puede ser digital, números que se mueven entre cuentas, no solo monedas y billetes físicos que puedes sostener. Cuando mamá acercó su tarjeta, ninguna moneda ni billete cambió de manos. En cambio, un número bajó en su cuenta, y un número subió en la cuenta de la tienda. ¡Pago recibido! Sigue siendo dinero de verdad, solo que se mueve de otra manera. Palabra nueva: el dinero digital es dinero que existe como números en un ordenador, no como monedas o billetes que puedes sostener.",
    fr: "L'argent que tu ne peux pas tenir dans ta main. Parfois, l'argent ne ressemble pas du tout à des pièces. Voyons ce que ça veut dire ! Alors l'argent peut être numérique ? Idée clé : l'argent peut être numérique, des chiffres qui se déplacent entre des comptes, pas seulement des pièces et des billets physiques que tu peux tenir. Quand maman a approché sa carte, aucune pièce ni aucun billet n'a changé de main. À la place, un chiffre a baissé sur son compte, et un chiffre a augmenté sur le compte du magasin. Paiement reçu ! C'est toujours de l'argent réel, il se déplace juste d'une autre manière. Nouveau mot : l'argent numérique est de l'argent qui existe sous forme de chiffres sur un ordinateur, pas comme des pièces ou des billets que tu peux tenir.",
    de: "Geld, das du nicht anfassen kannst. Manchmal sieht Geld überhaupt nicht wie Münzen aus. Schauen wir uns an, was das bedeutet! Kann Geld also digital sein? Kernidee: Geld kann digital sein, Zahlen, die sich zwischen Konten bewegen, nicht nur echte Münzen und Scheine, die du anfassen kannst. Als Mama ihre Karte antippte, wechselten keine Münzen oder Scheine den Besitzer. Stattdessen sank eine Zahl auf ihrem Konto, und eine Zahl stieg auf dem Konto des Geschäfts. Zahlung erhalten! Es ist immer noch echtes Geld, es bewegt sich nur auf eine andere Weise. Neues Wort: Digitales Geld ist Geld, das als Zahlen auf einem Computer existiert, nicht als Münzen oder Scheine, die du anfassen kannst.",
    it: "Il denaro che non puoi tenere in mano. A volte il denaro non assomiglia per niente alle monete. Vediamo cosa vuol dire! Quindi il denaro può essere digitale? Idea chiave: il denaro può essere digitale, numeri che si spostano tra conti, non solo monete e banconote fisiche che puoi tenere in mano. Quando la mamma ha avvicinato la sua carta, nessuna moneta o banconota è passata di mano. Invece, un numero è sceso sul suo conto, e un numero è salito sul conto del negozio. Pagamento ricevuto! È comunque denaro vero, si sposta solo in un altro modo. Parola nuova: il denaro digitale è denaro che esiste come numeri su un computer, non come monete o banconote che puoi tenere in mano.",
    pt: "O dinheiro que não se pode segurar. Às vezes, o dinheiro não se parece nada com moedas. Vamos ver o que isso significa! Então o dinheiro pode ser digital? Ideia-chave: o dinheiro pode ser digital, números que se movem entre contas, não apenas moedas e notas físicas que podes segurar. Quando a mãe encostou o cartão, nenhuma moeda ou nota mudou de mãos. Em vez disso, um número desceu na conta dela, e um número subiu na conta da loja. Pagamento recebido! Continua a ser dinheiro verdadeiro, só que se move de outra forma. Palavra nova: dinheiro digital é dinheiro que existe como números num computador, não como moedas ou notas que podes segurar.",
    nl: "Geld dat je niet kunt vasthouden. Soms ziet geld er helemaal niet uit als munten. Laten we kijken wat dat betekent! Dus geld kan digitaal zijn? Kernidee: geld kan digitaal zijn, cijfers die tussen rekeningen bewegen, niet alleen fysieke munten en briefjes die je kunt vasthouden. Toen mama haar pas tikte, wisselden er geen munten of briefjes van eigenaar. In plaats daarvan ging een getal omlaag op haar rekening, en ging een getal omhoog op de rekening van de winkel. Betaling ontvangen! Het is nog steeds echt geld, het beweegt alleen op een andere manier. Nieuw woord: digitaal geld is geld dat bestaat als cijfers op een computer, niet als munten of briefjes die je kunt vasthouden.",
    pl: "Pieniądze, których nie można trzymać w ręce. Czasami pieniądze wcale nie wyglądają jak monety. Zobaczmy, co to znaczy! Czy więc pieniądze mogą być cyfrowe? Najważniejsza myśl: pieniądze mogą być cyfrowe, czyli liczby, które przemieszczają się między kontami, a nie tylko fizyczne monety i banknoty, które można trzymać w ręce. Kiedy mama przyłożyła kartę, żadna moneta ani banknot nie zmieniły właściciela. Zamiast tego liczba na jej koncie zmalała, a liczba na koncie sklepu wzrosła. Płatność otrzymana! To nadal prawdziwe pieniądze, tylko poruszają się w inny sposób. Nowe słowo: pieniądze cyfrowe to pieniądze, które istnieją jako liczby w komputerze, a nie jako monety czy banknoty, które można trzymać w ręce.",
  },
  junior_isa: {
    en: "A Junior ISA. In the United Kingdom, there's a special kind of savings account that belongs to a child, even though a grown-up manages it. It's called a Junior ISA! Key idea: a Junior ISA is a UK savings account that belongs to a child, even though a parent or guardian manages it for them while they're young. A Junior ISA is opened by a parent or guardian, but the money inside genuinely belongs to you. It's for your future! You can save in your Junior ISA for bigger goals, like a bike, a laptop, or your education. Other countries have different systems for helping children save, so a Junior ISA specifically is a United Kingdom thing. New words: a Junior ISA is a UK savings account for children, managed by a parent or guardian, where the money belongs to the child. The UK is the United Kingdom, the country where you live if you're in England, Scotland, Wales, or Northern Ireland.",
    ro: "Un Junior ISA. În Regatul Unit, există un tip special de cont de economii care aparține unui copil, chiar dacă un adult îl administrează. Se numește Junior ISA! Idee cheie: un Junior ISA este un cont de economii din Regatul Unit care aparține unui copil, chiar dacă un părinte sau un tutore îl administrează pentru el cât timp e mic. Un Junior ISA este deschis de un părinte sau de un tutore, dar banii din el îți aparțin cu adevărat ție. Sunt pentru viitorul tău! Poți economisi în Junior ISA pentru obiective mai mari, cum ar fi o bicicletă, un laptop sau educația ta. Alte țări au sisteme diferite prin care îi ajută pe copii să economisească, așa că un Junior ISA este specific Regatului Unit. Cuvinte noi: un Junior ISA este un cont de economii din Regatul Unit pentru copii, administrat de un părinte sau de un tutore, în care banii aparțin copilului. UK înseamnă Regatul Unit, țara în care trăiești dacă ești în Anglia, Scoția, Țara Galilor sau Irlanda de Nord.",
    es: "Una Junior ISA. En el Reino Unido existe un tipo especial de cuenta de ahorro que pertenece a un niño o una niña, aunque la gestione una persona adulta. ¡Se llama Junior ISA! Idea clave: una Junior ISA es una cuenta de ahorro del Reino Unido que pertenece a un niño o una niña, aunque un padre, una madre o un tutor la gestione mientras es pequeño. Una Junior ISA la abre un padre, una madre o un tutor, pero el dinero que hay dentro es realmente tuyo. ¡Es para tu futuro! Puedes ahorrar en tu Junior ISA para metas más grandes, como una bicicleta, un ordenador portátil o tus estudios. Otros países tienen sistemas diferentes para ayudar a los niños a ahorrar, así que una Junior ISA es algo específico del Reino Unido. Palabras nuevas: una Junior ISA es una cuenta de ahorro del Reino Unido para niños, gestionada por un padre, una madre o un tutor, donde el dinero pertenece al niño o la niña. El Reino Unido es el país donde vives si estás en Inglaterra, Escocia, Gales o Irlanda del Norte.",
    fr: "Un Junior ISA. Au Royaume-Uni, il existe un type spécial de compte d'épargne qui appartient à un enfant, même si c'est un adulte qui le gère. On l'appelle Junior ISA ! Idée clé : un Junior ISA est un compte d'épargne du Royaume-Uni qui appartient à un enfant, même si un parent ou un tuteur le gère pour lui pendant qu'il est jeune. Un Junior ISA est ouvert par un parent ou un tuteur, mais l'argent qu'il contient t'appartient vraiment. C'est pour ton avenir ! Tu peux épargner dans ton Junior ISA pour des objectifs plus grands, comme un vélo, un ordinateur portable ou tes études. D'autres pays ont des systèmes différents pour aider les enfants à épargner, donc un Junior ISA est vraiment une chose propre au Royaume-Uni. Nouveaux mots : un Junior ISA est un compte d'épargne du Royaume-Uni pour les enfants, géré par un parent ou un tuteur, dans lequel l'argent appartient à l'enfant. Le Royaume-Uni est le pays où tu vis si tu es en Angleterre, en Écosse, au Pays de Galles ou en Irlande du Nord.",
    de: "Ein Junior ISA. Im Vereinigten Königreich gibt es eine besondere Art von Sparkonto, das einem Kind gehört, auch wenn ein Erwachsener es verwaltet. Es heißt Junior ISA! Kernidee: Ein Junior ISA ist ein Sparkonto aus dem Vereinigten Königreich, das einem Kind gehört, auch wenn ein Elternteil oder Vormund es für das Kind verwaltet, solange es jung ist. Ein Junior ISA wird von einem Elternteil oder Vormund eröffnet, aber das Geld darin gehört wirklich dir. Es ist für deine Zukunft! Du kannst in deinem Junior ISA für größere Ziele sparen, wie ein Fahrrad, einen Laptop oder deine Ausbildung. Andere Länder haben unterschiedliche Systeme, um Kindern beim Sparen zu helfen, daher ist ein Junior ISA speziell eine Sache aus dem Vereinigten Königreich. Neue Wörter: Ein Junior ISA ist ein Sparkonto aus dem Vereinigten Königreich für Kinder, verwaltet von einem Elternteil oder Vormund, bei dem das Geld dem Kind gehört. Das Vereinigte Königreich ist das Land, in dem du lebst, wenn du in England, Schottland, Wales oder Nordirland wohnst.",
    it: "Un Junior ISA. Nel Regno Unito esiste un tipo speciale di conto di risparmio che appartiene a un bambino, anche se è un adulto a gestirlo. Si chiama Junior ISA! Idea chiave: un Junior ISA è un conto di risparmio del Regno Unito che appartiene a un bambino, anche se un genitore o un tutore lo gestisce per lui finché è piccolo. Un Junior ISA viene aperto da un genitore o da un tutore, ma il denaro al suo interno appartiene davvero a te. È per il tuo futuro! Puoi risparmiare nel tuo Junior ISA per obiettivi più grandi, come una bicicletta, un computer portatile o i tuoi studi. Altri paesi hanno sistemi diversi per aiutare i bambini a risparmiare, quindi un Junior ISA è proprio una cosa del Regno Unito. Parole nuove: un Junior ISA è un conto di risparmio del Regno Unito per bambini, gestito da un genitore o da un tutore, in cui il denaro appartiene al bambino. Il Regno Unito è il paese in cui vivi se ti trovi in Inghilterra, Scozia, Galles o Irlanda del Nord.",
    pt: "Uma Junior ISA. No Reino Unido, existe um tipo especial de conta poupança que pertence a uma criança, mesmo que seja um adulto a geri-la. Chama-se Junior ISA! Ideia-chave: uma Junior ISA é uma conta poupança do Reino Unido que pertence a uma criança, mesmo que um pai, uma mãe ou um tutor a geria por ela enquanto é pequena. Uma Junior ISA é aberta por um pai, uma mãe ou um tutor, mas o dinheiro lá dentro pertence mesmo a ti. É para o teu futuro! Podes poupar na tua Junior ISA para objetivos maiores, como uma bicicleta, um computador portátil ou os teus estudos. Outros países têm sistemas diferentes para ajudar as crianças a poupar, por isso uma Junior ISA é especificamente uma coisa do Reino Unido. Palavras novas: uma Junior ISA é uma conta poupança do Reino Unido para crianças, gerida por um pai, uma mãe ou um tutor, em que o dinheiro pertence à criança. O Reino Unido é o país onde vives se estiveres em Inglaterra, Escócia, País de Gales ou Irlanda do Norte.",
    nl: "Een Junior ISA. In het Verenigd Koninkrijk bestaat een speciale soort spaarrekening die van een kind is, ook al beheert een volwassene die. Het heet een Junior ISA! Kernidee: een Junior ISA is een spaarrekening uit het Verenigd Koninkrijk die van een kind is, ook al beheert een ouder of voogd die voor het kind zolang het jong is. Een Junior ISA wordt geopend door een ouder of voogd, maar het geld erin is echt van jou. Het is voor jouw toekomst! Je kunt in je Junior ISA sparen voor grotere doelen, zoals een fiets, een laptop, of je opleiding. Andere landen hebben andere systemen om kinderen te helpen sparen, dus een Junior ISA is echt iets van het Verenigd Koninkrijk. Nieuwe woorden: een Junior ISA is een spaarrekening uit het Verenigd Koninkrijk voor kinderen, beheerd door een ouder of voogd, waarbij het geld van het kind is. Het VK is het Verenigd Koninkrijk, het land waar je woont als je in Engeland, Schotland, Wales of Noord-Ierland bent.",
    pl: "Junior ISA. W Wielkiej Brytanii istnieje specjalny rodzaj konta oszczędnościowego, które należy do dziecka, mimo że zarządza nim osoba dorosła. Nazywa się Junior ISA! Najważniejsza myśl: Junior ISA to brytyjskie konto oszczędnościowe, które należy do dziecka, mimo że rodzic lub opiekun zarządza nim w jego imieniu, dopóki jest małe. Junior ISA zakłada rodzic lub opiekun, ale pieniądze na nim naprawdę należą do ciebie. Są na twoją przyszłość! Możesz oszczędzać na swoim Junior ISA na większe cele, takie jak rower, laptop czy twoją edukację. Inne kraje mają inne systemy pomagające dzieciom oszczędzać, więc Junior ISA to coś typowo brytyjskiego. Nowe słowa: Junior ISA to brytyjskie konto oszczędnościowe dla dzieci, zarządzane przez rodzica lub opiekuna, na którym pieniądze należą do dziecka. UK to Wielka Brytania, kraj, w którym mieszkasz, jeśli jesteś w Anglii, Szkocji, Walii lub Irlandii Północnej.",
  },
  investing_basics: {
    en: "Saving vs Growing Your Money. Saving keeps your coins safe, but investing is different! Let's see how money can grow! But it isn't guaranteed. Key idea: saving keeps money safe and unchanged until you add to it. Investing means using money to try to grow it over time, but the amount can go up or down — it's never guaranteed. A savings jar only changes when you put more coins in or take some out. Investing is different: grown-ups sometimes use money to become part-owners of things, like companies, hoping the value grows, but it can shrink too. Nobody can promise investing will make more money. New words: saving means keeping money safe and unchanged. Investing means using money to try to grow it over time, but it can go up or down.",
    ro: "Economisire sau creșterea banilor? A economisi îți păstrează monedele în siguranță, dar a investi e altceva! Hai să vedem cum pot crește banii! Dar nu e garantat. Idee cheie: economisirea păstrează banii în siguranță și neschimbați până adaugi mai mult. A investi înseamnă să folosești bani ca să încerci să îi faci să crească în timp, dar suma poate crește sau scădea — nu este niciodată garantat. Un borcan de economii se schimbă doar când pui mai multe monede sau scoți câteva. A investi e altceva: adulții folosesc uneori bani ca să devină coproprietari ai unor lucruri, cum ar fi companii, sperând că valoarea va crește, dar aceasta poate și să scadă. Nimeni nu poate promite că investiția va aduce mai mulți bani. Cuvinte noi: a economisi înseamnă a păstra banii în siguranță și neschimbați. A investi înseamnă a folosi bani ca să încerci să-i faci să crească în timp, dar pot crește sau scădea.",
    es: "Ahorrar o hacer crecer tu dinero. ¡Ahorrar mantiene tus monedas seguras, pero invertir es diferente! ¡Vamos a ver cómo puede crecer el dinero! Pero no está garantizado. Idea clave: ahorrar mantiene el dinero seguro y sin cambios hasta que añades más. Invertir significa usar dinero para intentar hacerlo crecer con el tiempo, pero la cantidad puede subir o bajar; nunca está garantizado. Un bote de ahorros solo cambia cuando metes más monedas o sacas algunas. Invertir es diferente: las personas adultas a veces usan dinero para convertirse en copropietarias de cosas, como empresas, con la esperanza de que el valor crezca, pero también puede reducirse. Nadie puede prometer que invertir hará que tengas más dinero. Palabras nuevas: ahorrar significa mantener el dinero seguro y sin cambios. Invertir significa usar dinero para intentar hacerlo crecer con el tiempo, aunque puede subir o bajar.",
    fr: "Épargner ou faire grandir son argent. Épargner garde tes pièces en sécurité, mais investir, c'est différent ! Voyons comment l'argent peut grandir ! Mais ce n'est pas garanti. Idée clé : épargner garde l'argent en sécurité et inchangé jusqu'à ce que tu en ajoutes. Investir, c'est utiliser de l'argent pour essayer de le faire grandir avec le temps, mais la somme peut monter ou descendre, ce n'est jamais garanti. Une tirelire ne change que lorsque tu y mets plus de pièces ou que tu en retires. Investir, c'est différent : les adultes utilisent parfois de l'argent pour devenir copropriétaires de choses, comme des entreprises, en espérant que leur valeur augmente, mais elle peut aussi diminuer. Personne ne peut promettre qu'investir rapportera plus d'argent. Nouveaux mots : épargner veut dire garder l'argent en sécurité et inchangé. Investir veut dire utiliser de l'argent pour essayer de le faire grandir avec le temps, mais il peut monter ou descendre.",
    de: "Sparen oder dein Geld wachsen lassen. Sparen hält deine Münzen sicher, aber Investieren ist anders! Schauen wir uns an, wie Geld wachsen kann! Aber das ist nicht garantiert. Kernidee: Sparen hält Geld sicher und unverändert, bis du mehr hinzufügst. Investieren bedeutet, Geld zu benutzen, um zu versuchen, es über die Zeit wachsen zu lassen, aber der Betrag kann steigen oder sinken — das ist nie garantiert. Ein Sparglas ändert sich nur, wenn du mehr Münzen hineinlegst oder welche herausnimmst. Investieren ist anders: Erwachsene benutzen manchmal Geld, um Mitbesitzer von Dingen zu werden, wie Unternehmen, in der Hoffnung, dass der Wert wächst, aber er kann auch schrumpfen. Niemand kann versprechen, dass Investieren mehr Geld einbringt. Neue Wörter: Sparen bedeutet, Geld sicher und unverändert zu halten. Investieren bedeutet, Geld zu benutzen, um es über die Zeit wachsen zu lassen, aber es kann steigen oder sinken.",
    it: "Risparmiare o far crescere i tuoi soldi. Risparmiare tiene al sicuro le tue monete, ma investire è diverso! Vediamo come può crescere il denaro! Ma non è garantito. Idea chiave: risparmiare tiene il denaro al sicuro e invariato finché non ne aggiungi altro. Investire significa usare il denaro per cercare di farlo crescere nel tempo, ma la somma può salire o scendere: non è mai garantito. Un barattolo dei risparmi cambia solo quando metti più monete o ne togli qualcuna. Investire è diverso: gli adulti a volte usano il denaro per diventare comproprietari di qualcosa, come le aziende, sperando che il valore cresca, ma può anche ridursi. Nessuno può promettere che investire farà guadagnare più denaro. Parole nuove: risparmiare significa tenere il denaro al sicuro e invariato. Investire significa usare il denaro per cercare di farlo crescere nel tempo, anche se può salire o scendere.",
    pt: "Poupar ou fazer crescer o teu dinheiro. Poupar mantém as tuas moedas seguras, mas investir é diferente! Vamos ver como o dinheiro pode crescer! Mas não é garantido. Ideia-chave: poupar mantém o dinheiro seguro e inalterado até adicionares mais. Investir significa usar dinheiro para tentar fazê-lo crescer ao longo do tempo, mas a quantia pode subir ou descer — nunca é garantido. Um frasco de poupanças só muda quando pões mais moedas ou tiras algumas. Investir é diferente: os adultos por vezes usam dinheiro para se tornarem coproprietários de coisas, como empresas, na esperança de que o valor cresça, mas também pode diminuir. Ninguém pode prometer que investir vai render mais dinheiro. Palavras novas: poupar significa manter o dinheiro seguro e inalterado. Investir significa usar dinheiro para tentar fazê-lo crescer ao longo do tempo, mas pode subir ou descer.",
    nl: "Sparen of je geld laten groeien. Sparen houdt je munten veilig, maar investeren is anders! Laten we kijken hoe geld kan groeien! Maar dat is niet gegarandeerd. Kernidee: sparen houdt geld veilig en ongewijzigd totdat je er meer aan toevoegt. Investeren betekent geld gebruiken om te proberen het na verloop van tijd te laten groeien, maar het bedrag kan stijgen of dalen — dat is nooit gegarandeerd. Een spaarpot verandert alleen als je er meer munten in stopt of er een paar uithaalt. Investeren is anders: volwassenen gebruiken geld soms om mede-eigenaar te worden van dingen, zoals bedrijven, in de hoop dat de waarde groeit, maar die kan ook krimpen. Niemand kan beloven dat investeren meer geld oplevert. Nieuwe woorden: sparen betekent geld veilig en ongewijzigd houden. Investeren betekent geld gebruiken om te proberen het na verloop van tijd te laten groeien, maar het kan stijgen of dalen.",
    pl: "Oszczędzanie czy pomnażanie pieniędzy. Oszczędzanie trzyma twoje monety bezpiecznie, ale inwestowanie to coś innego! Zobaczmy, jak pieniądze mogą rosnąć! Ale to nie jest gwarantowane. Najważniejsza myśl: oszczędzanie trzyma pieniądze bezpiecznie i bez zmian, dopóki nie dodasz więcej. Inwestowanie oznacza wykorzystywanie pieniędzy, by spróbować je pomnożyć z czasem, ale kwota może rosnąć lub maleć — to nigdy nie jest gwarantowane. Słoik z oszczędnościami zmienia się tylko wtedy, gdy wkładasz więcej monet albo je wyjmujesz. Inwestowanie to coś innego: dorośli czasem wykorzystują pieniądze, żeby stać się współwłaścicielami czegoś, na przykład firm, mając nadzieję, że wartość wzrośnie, ale może też zmaleć. Nikt nie może obiecać, że inwestowanie przyniesie więcej pieniędzy. Nowe słowa: oszczędzanie oznacza trzymanie pieniędzy bezpiecznie i bez zmian. Inwestowanie oznacza wykorzystywanie pieniędzy, by spróbować je pomnożyć z czasem, choć mogą rosnąć lub maleć.",
  },
};
